class FakeDatabase:
    def __init__(self):
        self.posts = {1: "Scaling Postgres", 2: "Intro to Read Replicas", 3: "Query Optimization 101"}
        self.authors = {1: "Asha", 2: "Marco", 3: "Asha"}
        self.query_count = 0

    def fetch_all_post_ids(self):
        self.query_count += 1
        return list(self.posts.keys())

    def fetch_author_for_post(self, post_id):
        self.query_count += 1
        return self.authors[post_id]

    def fetch_posts_with_authors_joined(self):
        self.query_count += 1
        return {post_id: self.authors[post_id] for post_id in self.posts}

    def reset_query_count(self):
        self.query_count = 0


# the N+1 problem: one query for the list, then one more per row
def run_n_plus_one(db):
    db.reset_query_count()
    post_ids = db.fetch_all_post_ids()
    for post_id in post_ids:
        author = db.fetch_author_for_post(post_id)  # N extra queries
        print(f"post {post_id} -> author {author}")
    print(f"N+1 approach used {db.query_count} queries for {len(post_ids)} posts")


# the fix: one query with a join instead of N extra round trips
def run_joined(db):
    db.reset_query_count()
    posts_with_authors = db.fetch_posts_with_authors_joined()
    for post_id, author in posts_with_authors.items():
        print(f"post {post_id} -> author {author}")
    print(f"Joined approach used {db.query_count} query for {len(posts_with_authors)} posts")


if __name__ == "__main__":
    database = FakeDatabase()
    run_n_plus_one(database)
    print()
    run_joined(database)

