import java.util.*;

class FakeDatabase {
    private final Map<Integer, String> posts = new LinkedHashMap<>();
    private final Map<Integer, String> authors = new HashMap<>();
    private int queryCount = 0;

    FakeDatabase() {
        posts.put(1, "Scaling Postgres");
        posts.put(2, "Intro to Read Replicas");
        posts.put(3, "Query Optimization 101");
        authors.put(1, "Asha");
        authors.put(2, "Marco");
        authors.put(3, "Asha");
    }

    List<Integer> fetchAllPostIds() {
        queryCount++;
        return new ArrayList<>(posts.keySet());
    }

    String fetchAuthorForPost(int postId) {
        queryCount++;
        return authors.get(postId);
    }

    Map<Integer, String> fetchPostsWithAuthorsJoined() {
        queryCount++;
        Map<Integer, String> joined = new LinkedHashMap<>();
        for (Map.Entry<Integer, String> e : posts.entrySet()) {
            joined.put(e.getKey(), authors.get(e.getKey()));
        }
        return joined;
    }

    int getQueryCount() {
        return queryCount;
    }

    void resetQueryCount() {
        queryCount = 0;
    }
}

public class Main {

    // the N+1 problem: one query for the list, then one more per row
    static void runNPlusOne(FakeDatabase db) {
        db.resetQueryCount();
        List<Integer> postIds = db.fetchAllPostIds();
        for (int postId : postIds) {
            String author = db.fetchAuthorForPost(postId); // N extra queries
            System.out.println("post " + postId + " -> author " + author);
        }
        System.out.println("N+1 approach used " + db.getQueryCount() + " queries for " + postIds.size() + " posts");
    }

    // the fix: one query with a join instead of N extra round trips
    static void runJoined(FakeDatabase db) {
        db.resetQueryCount();
        Map<Integer, String> postsWithAuthors = db.fetchPostsWithAuthorsJoined();
        for (Map.Entry<Integer, String> e : postsWithAuthors.entrySet()) {
            System.out.println("post " + e.getKey() + " -> author " + e.getValue());
        }
        System.out.println("Joined approach used " + db.getQueryCount() + " query for " + postsWithAuthors.size() + " posts");
    }

    public static void main(String[] args) {
        FakeDatabase db = new FakeDatabase();
        runNPlusOne(db);
        System.out.println();
        runJoined(db);
    }
}

