#include <iostream>
#include <map>
#include <vector>
#include <string>

class FakeDatabase {
public:
    FakeDatabase() {
        posts_ = {{1, "Scaling Postgres"}, {2, "Intro to Read Replicas"}, {3, "Query Optimization 101"}};
        authors_ = {{1, "Asha"}, {2, "Marco"}, {3, "Asha"}};
    }

    std::vector<int> fetchAllPostIds() {
        queryCount_++;
        std::vector<int> ids;
        for (const auto& kv : posts_) ids.push_back(kv.first);
        return ids;
    }

    std::string fetchAuthorForPost(int postId) {
        queryCount_++;
        return authors_[postId];
    }

    std::map<int, std::string> fetchPostsWithAuthorsJoined() {
        queryCount_++;
        std::map<int, std::string> joined;
        for (const auto& kv : posts_) joined[kv.first] = authors_[kv.first];
        return joined;
    }

    int getQueryCount() const { return queryCount_; }
    void resetQueryCount() { queryCount_ = 0; }

private:
    std::map<int, std::string> posts_;
    std::map<int, std::string> authors_;
    int queryCount_ = 0;
};

// the N+1 problem: one query for the list, then one more per row
void runNPlusOne(FakeDatabase& db) {
    db.resetQueryCount();
    std::vector<int> postIds = db.fetchAllPostIds();
    for (int postId : postIds) {
        std::string author = db.fetchAuthorForPost(postId); // N extra queries
        std::cout << "post " << postId << " -> author " << author << std::endl;
    }
    std::cout << "N+1 approach used " << db.getQueryCount() << " queries for " << postIds.size() << " posts" << std::endl;
}

// the fix: one query with a join instead of N extra round trips
void runJoined(FakeDatabase& db) {
    db.resetQueryCount();
    std::map<int, std::string> postsWithAuthors = db.fetchPostsWithAuthorsJoined();
    for (const auto& kv : postsWithAuthors) {
        std::cout << "post " << kv.first << " -> author " << kv.second << std::endl;
    }
    std::cout << "Joined approach used " << db.getQueryCount() << " query for " << postsWithAuthors.size() << " posts" << std::endl;
}

int main() {
    FakeDatabase db;
    runNPlusOne(db);
    std::cout << std::endl;
    runJoined(db);
    return 0;
}
